    if not cells:
        return g
    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    if max_r < line_r:
        delta = line_r - 1 - max_r
        dr = delta
        trail_r = min_r + delta - 1
    elif min_r > line_r:
        delta = min_r - (line_r + 1)
        dr = -delta
        trail_r = max_r - delta + 1
    else:
        return g
    for r, c in cells:
        g[r][c] = bg
    for r, c in cells:
        g[r + dr][c] = obj_color
    if 0 <= trail_r < h and trail_r != line_r:
        g[trail_r] = [8] * w
    return g
